"use client";

import { motion } from "framer-motion";

export function Hero() {
    return (
        <section className="flex min-h-[90vh] flex-col justify-center px-4 pt-20 sm:px-6 lg:px-8">
            <div className="mx-auto max-w-4xl text-left">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5 }}
                >
                    <span className="mb-4 block text-lg font-medium text-blue-400">
                        Hi, my name is
                    </span>
                    <h1 className="text-5xl font-bold tracking-tight text-white sm:text-7xl">
                        N. Pagalavan
                    </h1>
                    <h2 className="mt-4 text-4xl font-bold tracking-tight text-neutral-400 sm:text-6xl">
                        I build intelligent systems.
                    </h2>
                </motion.div>

                <motion.p
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: 0.2 }}
                    className="mt-6 max-w-2xl text-lg text-neutral-400"
                >
                    2nd year student at SRMIST and an aspiring Machine Learning intern. I have hands-on experience in model development, explainable AI, and building automation pipelines.
                </motion.p>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: 0.4 }}
                    className="mt-10 flex gap-4"
                >
                    <a
                        href="#contact"
                        className="rounded-lg bg-blue-600 px-6 py-3 text-sm font-medium text-white transition-colors hover:bg-blue-700"
                    >
                        Get in touch
                    </a>
                    <a
                        href="#projects"
                        className="rounded-lg border border-neutral-700 bg-transparent px-6 py-3 text-sm font-medium text-white transition-colors hover:bg-neutral-800"
                    >
                        Check out my work
                    </a>
                </motion.div>
            </div>
        </section>
    );
}
